// CC0 recorded wood/leather by Kenney and water by rubberduck. See public/assets/audio/ACTION-SOURCES-v22.txt.
// Preloaded mono PCM avoids network/codec dependence on the first gesture.
const encoded={
buy:'',
cast:'',
harvest:'',
};const cache=new Map();
export function recordedAction(kind,sampleRate=22050){const key=kind==='catch'?'harvest':kind;if(!encoded[key])return null;let data=cache.get(key);if(!data){const b=Uint8Array.from(atob(encoded[key]),c=>c.charCodeAt(0)),v=new DataView(b.buffer);data=Float32Array.from({length:b.length/2},(_,i)=>v.getInt16(i*2,true)/32768);cache.set(key,data);}if(sampleRate===22050)return data.slice();return Float32Array.from({length:Math.ceil(data.length*sampleRate/22050)},(_,i)=>{const p=i*22050/sampleRate,a=Math.floor(p),f=p-a;return(data[a]??0)*(1-f)+(data[a+1]??0)*f;});}
